109	fn parse_doc_type(p: &mut HtmlParser) -> ParsedSyntax {
110	    if !(p.at(T![<]) && p.nth_at(1, T![!])) {
111	        return Absent;
112	    }
113	
114	    let m = p.start();
115	    p.bump_with_context(T![<], HtmlLexContext::InsideTag);
116	    p.bump_with_context(T![!], HtmlLexContext::Doctype);
117	
118	    if p.at(T![doctype]) {
119	        p.eat_with_context(T![doctype], HtmlLexContext::Doctype);
120	    }
121	
122	    if p.at(T![html]) {
123	        p.eat_with_context(T![html], HtmlLexContext::Doctype);
124	    }
125	
126	    if p.at(HTML_LITERAL) {
127	        p.eat_with_context(HTML_LITERAL, HtmlLexContext::Doctype);
128	    }
129	
130	    if p.at(HTML_STRING_LITERAL) {
131	        p.eat_with_context(HTML_STRING_LITERAL, HtmlLexContext::Doctype);
132	    }
133	
134	    if p.at(HTML_STRING_LITERAL) {
135	        p.eat_with_context(HTML_STRING_LITERAL, HtmlLexContext::Doctype);
136	    }
137	
138	    p.eat(T![>]);
139	
140	    Present(m.complete(p, HTML_DIRECTIVE))
141	}
